int main() {
    vector<int> a = {0, 1, 2, 3, 5, 7, 8, 9}; // Use vector from Parent 2
    int n;
    const int maxPower = 10; // Adjust as needed
    long long powers[maxPower];

    // Precompute powers of 8 using a single loop and static memory
    powers[0] = 1; // 8^0
    for (int i = 1; i < maxPower; i++) {
        powers[i] = powers[i - 1] * 8; // 8^i = 8^(i-1) * 8
    }

    while (cin >> n && n) {
        int i = maxPower - 1;
        while (i >= 0 && powers[i] > n) {
            i--;
        }

        for (; i >= 0; i--) {
            cout << a[n / powers[i]];
            n %= powers[i];
        }
        cout << endl;
    }

    return 0;
}

